  cloth.position.set(0, h - 0.8, 0); g.add(cloth); g.position.set(x, groundAt(x, z), z); g.rotation.y = rot; scene.add(SH(onLayer1(g)));
  FLAGS.push({ geo, base: geo.attributes.position.array.slice() });
