  for (const sd of [-1, 1]) { const c = new THREE.Mesh(CRATE_GEO, MAT.vc); c.position.set(x + lat[0] * sd * 1.95 + oo[0] * 0.3, g0, z + lat[1] * sd * 1.95 + oo[1] * 0.3); c.rotation.y = -b + sd * 0.25; scene.add(SH(onLayer1(c))); }
