const FM_CLOCK = ['15.10.1973 · צומת טרטור–לכסיקון', '15.10.1973 · הצומת', '16.10.1973 · החצר, התעלה', '17.10.1973 · ציר טרטור', '17.10.1973 · ציר טרטור, עם שחר', '17.10.1973 · החצר, שפת התעלה'];
