  for (let t = 2; t < FM_DZ.length; t++) for (let x = FM_FARM.x0 + 8; x < FM_FARM.x1 - 4; x += 14) { if (cross(x, FM_DX)) continue; S(x, FM_DZ[t] + 0.8, 0, 1, DY, 'PS', { pl: { j: t - 2 } }); }
