  fieldFriends([fmDef('חובש', FM_HT1[0] + 4.3, FM_HT1[1] - 1.1, [1, 0.3]), fmDef(FM_NAMES1[0], -282, -224, [0, -1]), fmDef(FM_NAMES1[1], -256, -229, [0.4, -1])]);
  // which craters hold ours is decided now, and kept by every save
