    if (FM.holdT <= 0 && !FM.msgs.dawn) { FM.msgs.dawn = true; radio('קשר', 'אור ראשון. טנקים ונגמ״שים בדרך אליכם — תחזיקו את הפצועים!', 3.6); DIRQ.push({ at: GAME.t + 3.5, fn: () => fmCut(() => fmSetup(S_SMOKE)) }); }
