  const [px, pz] = RGW(0, 52); P.pos.set(px, hAt(px, pz), pz); P.yaw = 0; P.pitch = -0.02;
  fieldFriends(RG_FRIENDS.map(([lx, name]) => { const [x, z] = RGW(lx, 41.4); return { name, x, z, fx: 0, fz: -1 }; }));
