function markDone(m) { PROG.done.add(m); try { localStorage.setItem('yk73.done', JSON.stringify([...PROG.done])); } catch (e) {} }
function markLast(m) { PROG.last = m; try { localStorage.setItem('yk73.last', m); } catch (e) {} }
